-- Shared platform-controlled corpus; matter records are excluded.
PRAGMA foreign_keys = ON;
CREATE TABLE legal_sources(source_id TEXT PRIMARY KEY,authority TEXT NOT NULL,source_page TEXT NOT NULL,access_status TEXT NOT NULL DEFAULT 'unknown',collection_permission TEXT NOT NULL DEFAULT 'unknown' CHECK(collection_permission IN ('unknown','allowed','allowed_limited','prohibited','not_allowed_without_explicit_exception_or_license')),commercial_reuse_permission TEXT NOT NULL DEFAULT 'unknown',terms_url TEXT,terms_checked_on TEXT,permission_evidence TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE legal_documents(document_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES legal_sources(source_id),official_title TEXT NOT NULL,document_type TEXT NOT NULL,practice_area TEXT NOT NULL DEFAULT 'unknown',law_number TEXT,law_year INTEGER,language TEXT NOT NULL DEFAULT 'ar',created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE legal_document_versions(version_id INTEGER PRIMARY KEY,document_id TEXT NOT NULL REFERENCES legal_documents(document_id),version_label TEXT NOT NULL,source_url TEXT NOT NULL,original_path TEXT,original_sha256 TEXT,retrieved_at TEXT,publication_date TEXT,effective_date TEXT,repeal_date TEXT,consolidated_as_of TEXT,gazette_issue TEXT,gazette_pages TEXT,legal_status TEXT NOT NULL DEFAULT 'unknown' CHECK(legal_status IN ('unknown','under_review','not_yet_in_force','in_force','partially_repealed','repealed','historical')),review_status TEXT NOT NULL DEFAULT 'pending_source_review' CHECK(review_status IN ('pending_source_review','pending_lawyer_review','verified','rejected')),authenticity_verified INTEGER NOT NULL DEFAULT 0 CHECK(authenticity_verified IN (0,1)),status_verified INTEGER NOT NULL DEFAULT 0 CHECK(status_verified IN (0,1)),amendment_history_verified INTEGER NOT NULL DEFAULT 0 CHECK(amendment_history_verified IN (0,1)),permission_evidence TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),UNIQUE(document_id,version_label));
CREATE TABLE legal_version_relations(relation_id INTEGER PRIMARY KEY,from_version_id INTEGER NOT NULL REFERENCES legal_document_versions(version_id),to_version_id INTEGER NOT NULL REFERENCES legal_document_versions(version_id),relation_type TEXT NOT NULL CHECK(relation_type IN ('amends','repeals','consolidates','corrects','supersedes','implements')),notes TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),CHECK(from_version_id<>to_version_id),UNIQUE(from_version_id,to_version_id,relation_type));
CREATE TABLE legal_review_events(review_event_id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES legal_document_versions(version_id),reviewer TEXT NOT NULL,review_type TEXT NOT NULL CHECK(review_type IN ('source_authenticity','extraction_quality','legal_status','amendment_history','licensing','lawyer_approval')),outcome TEXT NOT NULL CHECK(outcome IN ('pending','pass','fail','needs_correction')),notes TEXT NOT NULL DEFAULT '',evidence_url TEXT,reviewed_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE chunks(id INTEGER PRIMARY KEY,ref TEXT,article TEXT,page TEXT,text TEXT NOT NULL,norm TEXT NOT NULL,document_version_id INTEGER NOT NULL REFERENCES legal_document_versions(version_id),in_force INTEGER NOT NULL DEFAULT 0,as_of TEXT,source TEXT,verified INTEGER NOT NULL DEFAULT 0);
CREATE VIRTUAL TABLE chunks_fts USING fts5(norm,content='chunks',content_rowid='id');
CREATE TRIGGER chunks_fts_insert AFTER INSERT ON chunks BEGIN INSERT INTO chunks_fts(rowid,norm) VALUES(new.id,new.norm); END;
CREATE TRIGGER chunks_fts_delete AFTER DELETE ON chunks BEGIN INSERT INTO chunks_fts(chunks_fts,rowid,norm) VALUES('delete',old.id,old.norm); END;
CREATE TRIGGER chunks_fts_update AFTER UPDATE OF norm ON chunks BEGIN INSERT INTO chunks_fts(chunks_fts,rowid,norm) VALUES('delete',old.id,old.norm); INSERT INTO chunks_fts(rowid,norm) VALUES(new.id,new.norm); END;
CREATE INDEX idx_legal_documents_source_id ON legal_documents(source_id);
CREATE INDEX idx_legal_versions_document_id ON legal_document_versions(document_id,version_id);
CREATE INDEX idx_legal_chunks_version_id ON chunks(document_version_id);
